"""Audio recording regression using a synthetic microphone, never real hardware.
Requires Playwright, Chromium and a local OUTBASE server.
Run: OUTBASE_TEST_URL=http://127.0.0.1:8766/ python tests/execution-audio-flow.py
"""
import os
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-fake-device-for-media-stream'])
 c=b.new_context(viewport={'width':393,'height':852},timezone_id='Asia/Tokyo',permissions=['microphone']);page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 base=os.environ.get('OUTBASE_TEST_URL','http://127.0.0.1:8766/').rstrip('/')+'/'
 page.goto(base+'?shell=1&view=plan-editor&returnShell=home');form=page.locator('[data-ob22-plan-form]');form.wait_for();page.wait_for_timeout(1100);form.locator('[name=title]').fill('録音保存検証');form.locator('button[type=submit]').click();page.wait_for_url('**view=activity**');aid=page.evaluate('OUTBASE_ROUTER.current().activityId');record_url=base+'?shell=1&view=record&activityId='+aid
 page.goto(record_url);page.locator('[data-ob19-feature=audio]').wait_for();page.wait_for_timeout(400);page.locator('[data-ob19-feature=audio]').click()
 page.evaluate('()=>{window.originalAudioGetUserMedia=navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);navigator.mediaDevices.getUserMedia=()=>Promise.reject(new DOMException("denied","NotAllowedError"))}')
 page.locator('[data-ob19-audio-start]').click();page.get_by_text('マイクが許可されていません。ブラウザの設定で許可してからお試しください。',exact=True).wait_for();assert page.evaluate('async()=> (await OUTBASE_REPOSITORIES_V160.records.all()).length')==0;print('Permission denial visible; no writes: PASS',flush=True)
 page.evaluate('()=>{navigator.mediaDevices.getUserMedia=async constraints=>{const stream=await window.originalAudioGetUserMedia(constraints);window.testAudioStream=stream;return stream}}')
 page.locator('[data-ob19-audio-start]').click();page.locator('[data-ob19-audio-stop]').wait_for();page.wait_for_timeout(750);page.locator('[data-ob19-audio-stop]').click();page.locator('[data-ob19-audio-save]').wait_for();assert page.evaluate('window.testAudioStream.getTracks().every(track=>track.readyState==="ended")');assert page.evaluate('async()=> (await OUTBASE_REPOSITORIES_V160.records.all()).length')==0;print('Recording stops and releases microphone before explicit save: PASS',flush=True)
 page.locator('[data-ob19-audio-draft]').evaluate('async audio=>{await Promise.race([audio.play(),new Promise((_,reject)=>setTimeout(()=>reject(Error("playback timeout")),5000))]);audio.pause()}');print('Unsaved recording can be played for review: PASS',flush=True)
 page.evaluate('()=>{window.audioPut=IDBObjectStore.prototype.put;IDBObjectStore.prototype.put=function(...args){if(this.name==="media")throw new DOMException("quota","QuotaExceededError");return window.audioPut.apply(this,args)}}')
 page.locator('[data-ob19-audio-save]').click();page.get_by_text('音声を保存できませんでした。録音は残っています。もう一度お試しください。',exact=True).wait_for();assert page.evaluate('async()=> [(await OUTBASE_REPOSITORIES_V160.records.all()).length,(await OUTBASE_REPOSITORIES_V160.media.all()).length]')==[0,0];assert page.locator('[data-ob19-audio-draft]').count()==1;print('Storage failure rolls back both rows and retains recording: PASS',flush=True)
 page.evaluate('()=>{IDBObjectStore.prototype.put=window.audioPut}');c.set_offline(True);page.locator('[data-ob19-audio-save]').evaluate('(button)=>{button.click();button.click()}');page.locator('[data-ob19-audio-key]').wait_for();page.wait_for_function('document.querySelector("[data-ob19-audio-key]")?.readyState>=1')
 saved=page.evaluate('async()=>{const media=(await OUTBASE_REPOSITORIES_V160.media.all())[0],records=await OUTBASE_REPOSITORIES_V160.records.all();return {count:records.length,type:records[0].type,activityId:media.activity_id,kind:media.media_type,size:media.blob.size}}');assert saved['count']==1 and saved['type']=='audio' and saved['kind']=='audio' and saved['activityId']==aid and saved['size']>0;print('Offline recording save is linked to source activity without duplicate or transcript: PASS',flush=True)
 backup=page.evaluate('async()=>{const result=await OUTBASE_STORAGE_EXPORT_V1.createArchive({includeCacheStorage:false,databaseNames:["outbase_story_db"]});return await OUTBASE_ISOLATED_ARCHIVE_VERIFIER_V1.verify(result.archive,{explicit:true})}');assert backup['ok'] and not backup['currentDatabasesModified'];print('Audio backup roundtrip verified without changing source DB: PASS',flush=True)
 c.set_offline(False);page.reload();page.wait_for_function('globalThis.OUTBASE_SHELL_V166 !== undefined');page.evaluate('async()=>{await Promise.race([OUTBASE_SHELL_V166.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error("app readiness timeout")),15000))])}');page.locator('[data-ob19-audio-key]').wait_for();page.wait_for_timeout(500);page.locator('[data-ob19-audio-key]').click(position={'x':18,'y':25});page.locator('[data-ob19-audio-key]').evaluate('async audio=>{await Promise.race([audio.play(),new Promise((_,reject)=>setTimeout(()=>reject(Error("playback timeout")),5000))])}');assert page.locator('[data-ob19-audio-key]').evaluate('audio=>!audio.paused');print('Saved audio restored and plays after reload: PASS',flush=True)
 page.evaluate('()=>{const original=navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);navigator.mediaDevices.getUserMedia=async constraints=>{const stream=await original(constraints);window.testAudioStream=stream;return stream}}');page.locator('[data-ob19-feature=audio]').click();page.locator('[data-ob19-audio-start]').click();page.locator('[data-ob19-audio-stop]').wait_for();page.wait_for_timeout(500);page.get_by_role('button',name='ホーム',exact=True).click();page.wait_for_url('**view=home**');page.wait_for_function('window.testAudioStream.getTracks().every(track=>track.readyState==="ended")');page.wait_for_function('id=>OUTBASE_AUDIO_RECORDER.snapshot(id).status==="ready"',arg=aid);print('Navigation stops recording and releases microphone: PASS',flush=True)
 page.locator('a.ob36-plan').filter(has_text='録音保存検証').click();page.locator('[data-ob17-context=record]').first.click();page.locator('[data-ob19-audio-save]').wait_for();page.locator('[data-ob19-audio-cancel]').click();assert page.evaluate('async()=> (await OUTBASE_REPOSITORIES_V160.records.all()).length')==1;print('Cancel discards unsaved clip without writing: PASS',flush=True)
 assert not errors,errors;print('JavaScript errors: NONE',flush=True);c.close();b.close()
